-- Veritabanı Oluşturma Komutu
CREATE DATABASE OgrenciBilgiSistemi;
USE OgrenciBilgiSistemi;

-- 1. INSERT (Veri Ekleme)
INSERT INTO Students (FirstName, LastName, Email, DepartmentId)
VALUES ('Ahmet', 'Yılmaz', 'ahmet@mail.com', 1);

-- 2. SELECT (Veri Okuma)
SELECT StudentId, FirstName, LastName FROM Students;

-- 3. UPDATE (Güncelleme)
UPDATE Students
SET Email = 'ahmet.yilmaz@yeni.com'
WHERE StudentId = 1;

-- 4. DELETE (Silme)
DELETE FROM Students
WHERE StudentId = 1;
